schema:
CREATE TABLE country (
  country_id,
  country_iso_code,
  country_name
);

CREATE TABLE language (
  language_code,
  language_id,
  language_name
);

CREATE TABLE movie_crew (
  department_id,
  job,
  movie_id,
  person_id
);

CREATE TABLE movie_languages (
  language_id,
  language_role_id,
  movie_id
);
